import{z as n,x as o,o as t,c as A,q as s,j as r,D as e,d as E,s as l,S as i}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"延迟测量 cyclictest","description":"","frontmatter":{"title":"延迟测量 cyclictest","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/latency-measurement.md","filePath":"cs/latency-measurement.md","lastUpdated":1791063341000}'),p={name:"cs/latency-measurement.md"};function B(d,a,m,_,T,h){const c=o("Mermaid");return t(),A("div",null,[a[2]||(a[2]=s('<h1 id="延迟测量-cyclictest" tabindex="-1">延迟测量 cyclictest <a class="header-anchor" href="#延迟测量-cyclictest" aria-label="Permalink to &quot;延迟测量 cyclictest&quot;">​</a></h1><div class="epigraph"><p>cyclictest 按设定周期醒来，记录「应当醒来」与「实际醒来」之差，画出内核调度与抢占延迟的尾部。</p><footer>—— 据 rt-tests 的 cyclictest 文档；OSADL 对实时 Linux 测量的实践</footer></div><p><a href="/cs/preempt-rt">PREEMPT_RT</a> 声称有界。<a href="/cs/eevdf">EEVDF</a> 声称尾延迟更好。缺口是 <strong>怎么量</strong>：cyclictest 测的是唤醒延迟，不是应用业务延迟。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>任务 <code>clock_nanosleep</code> 到点，看 now-expected。直方图：max 才是 RT 关心的。缺口：必须隔核、关 HT、注意 <a href="/cs/napi">NAPI</a> 与 ksoftirqd；tracer 本身扰动。本课不把 OSADL 农场的全部配置复制过来。</p><p><span class="marginnote">用户循环里的计时要用 CLOCK_MONOTONIC_RAW 一类，避免 NTP 跳。对象是调度延迟，不是网卡 RTT。</span></p><p><span class="marginnote">术语翻译：CLOCK_MONOTONIC_RAW 就是「不做任何校正的单调秒表」——普通 MONOTONIC 允许 NTP 微调时钟快慢（你睡一觉它可能悄悄改掉几毫秒），RAW 则从启动起只进不退、只按硬件节拍走，测微秒级抖动时必须用它。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>绑 FIFO 高优先级 → 周期性睡眠 → 记录差。对照 <a href="/cs/perf-sampling">perf</a> 后课：perf 看热点，cyclictest 看最坏唤醒。对照 <a href="/cs/blkio-cgroup">blkio</a>：I/O 负载是扰动源，应同时加压。对照 fsync：那是存储完成，不是 CPU 唤醒。</p>',9)),(t(),r(i,null,{default:e(()=>[l(c,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SL%5B%22nanosleep%20%E5%88%B0%E7%82%B9%22%5D%20--%3E%20WK%5B%22%E8%A2%AB%E8%B0%83%E5%BA%A6%E4%B8%8A%20CPU%22%5D%0A%20%20WK%20--%3E%20D%5B%22now%20-%20%E9%A2%84%E6%9C%9F%22%5D%0A%20%20D%20--%3E%20HIST%5B%22%E7%9B%B4%E6%96%B9%E5%9B%BE%E4%B8%8E%20max%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>测量把「实时」从口号变成分布。没有加压的 max 没有意义。不要写成示波器使用课。与 <a href="/cs/tickless-nohz">tickless</a> 后课：无 tick 会改变唤醒路径，测量要注明模式。</p><p>结果不可在虚拟机与裸机间直接比，除非声明半虚拟时钟。</p><p>实现上：无负载的 cyclictest 只测空闲路径，要同时用 hackbench 或网络打满。虚拟机里测的是宿主注入，不是裸机。CLOCK_MONOTONIC 可能含 NTP 调整，测抖动用 RAW。 读法上只引用<a href="/cs/preempt-rt">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p><span class="marginnote">常见误区：初学者空载跑一次 cyclictest，看到 max 只有 20 μs 就宣布系统实时性合格。实际上没加压时最坏路径——软中断风暴、锁竞争、缓存全冷——根本没被踩到；同样配置下打满网络再测，max 可能翻到几百微秒。无压 max 不是乐观估计，是无效数据。</span></p><p><span class="marginnote">数字实例：同一台裸机上，标准内核在 hackbench 加压下 max 唤醒延迟常到毫秒级；换 PREEMPT_RT 内核后通常压在几十微秒内，硬实时要求（如 \\(\\lt 100\\ \\mu s\\) 的运动控制）看的就是这个差值。这也解释了为什么报告 max 时必须同时写明压力与内核配置。</span></p>',6)),(t(),r(i,null,{default:e(()=>[l(c,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E5%AE%9A%E6%97%B6%E5%99%A8%E5%88%B0%E6%9C%9F%E6%97%B6%E5%88%BB%22%5D%20--%3E%20IRQ%5B%22%E7%A1%AC%E4%BB%B6%E4%B8%AD%E6%96%AD%3A%20%E6%97%B6%E9%92%9F%E4%BA%8B%E4%BB%B6%22%5D%0A%20%20IRQ%20--%3E%20SOFT%5B%22%E8%BD%AF%E4%B8%AD%E6%96%AD%20%2F%20ksoftirqd%20%E5%A4%84%E7%90%86%22%5D%0A%20%20SOFT%20--%3E%20SCHED%5B%22%E8%B0%83%E5%BA%A6%E5%99%A8%E9%80%89%E4%B8%AD%E9%AB%98%E4%BC%98%E5%85%88%E7%BA%A7%20FIFO%20%E4%BB%BB%E5%8A%A1%22%5D%0A%20%20SCHED%20--%3E%20CTX%5B%22%E4%B8%8A%E4%B8%8B%E6%96%87%E5%88%87%E6%8D%A2%20%2B%20%E7%BC%93%E5%AD%98%E5%8F%AF%E8%83%BD%E5%85%A8%E5%86%B7%22%5D%0A%20%20CTX%20--%3E%20RUN%5B%22%E4%BB%BB%E5%8A%A1%E7%9C%9F%E6%AD%A3%E5%BC%80%E8%B7%91%3A%20%E8%AE%B0%E5%BD%95%20now-expected%22%5D%0A%20%20LOAD%5B%22%E5%A4%96%E9%83%A8%E5%8A%A0%E5%8E%8B%3A%20%E7%BD%91%E7%BB%9C%2FIO%2Fhackbench%22%5D%20--%3E%7C%22%E5%88%B6%E9%80%A0%E6%8A%A2%E5%8D%A0%E4%B8%8E%E6%8E%92%E9%98%9F%22%7C%20SOFT%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p>这张图回答的问题：直方图里那几十微秒到底花在了哪。唤醒延迟不是单一环节，而是中断、软中断、调度、切换四段排队之和；加压的意义就是逼每一段都走它最坏的那条路，否则测到的只是空闲捷径。</p><p>本课在操作系统进阶的「调度进阶 / 公平、实时与能耗」课序里，对象是 <strong>延迟测量 cyclictest</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 tracing 事件。不保证手机 SoC 的数字可移植。下一课用 cgroup 管 CPU 组：组调度。</p><p>版本字段会变，课序钉的是机制对象「延迟测量 cyclictest」，不是某一主线内核的结构体名。 后课默认：唤醒延迟可用周期睡眠直方图刻画。cgroup cpu 控制器如何摊权重与限额，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>cyclictest 量周期唤醒误差的尾部。</li><li>必须加压与绑核才有解释力。</li><li>cgroup CPU 组调度是下一课。</li><li>出处：rt-tests cyclictest；OSADL；POSIX 时钟。</li></ul>',8))])}const C=n(p,[["render",B]]);export{u as __pageData,C as default};
